const lockKeyringState = `-- name: LockKeyringState :one
SELECT active_key_id
FROM keyring_state
FOR UPDATE
`

// LockKeyringState reads and locks the active key for its activation by `muster secrets rotate-key`.
func (q *Queries) LockKeyringState(ctx context.Context) (string, error) {
	row := q.db.QueryRow(ctx, lockKeyringState)
	var active_key_id string
	err := row.Scan(&active_key_id)
	return active_key_id, err
}

const notifyKeyring = `-- name: NotifyKeyring :exec
SELECT pg_notify($1::text, $2::text)
`

type NotifyKeyringParams struct {
	Channel string
	Payload string
}

// NotifyKeyring wakes every replica on the keyring channel once the transaction commits.
func (q *Queries) NotifyKeyring(ctx context.Context, arg NotifyKeyringParams) error {
	_, err := q.db.Exec(ctx, notifyKeyring, arg.Channel, arg.Payload)
	return err
}

const pruneReplicas = `-- name: PruneReplicas :execrows
DELETE FROM replicas
WHERE refreshed_at < $1
`

// PruneReplicas deletes the records of replicas not refreshed since refreshed_before, on the real clock.
func (q *Queries) PruneReplicas(ctx context.Context, refreshedBefore time.Time) (int64, error) {
	result, err := q.db.Exec(ctx, pruneReplicas, refreshedBefore)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const recordReplica = `-- name: RecordReplica :exec
INSERT INTO replicas (replica_id, hostname, version, key_ids, started_at, refreshed_at)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (replica_id) DO UPDATE
SET key_ids = EXCLUDED.key_ids, started_at = EXCLUDED.started_at, refreshed_at = EXCLUDED.refreshed_at
`

type RecordReplicaParams struct {
	ReplicaID   string
	Hostname    pgtype.Text
	Version     string
	KeyIds      []string
	StartedAt   time.Time
	RefreshedAt time.Time
}

// RecordReplica writes the replica's record at start and refreshes it; a pruned record comes back. started_at moves
// when the replica re-registers after it lost the database.
func (q *Queries) RecordReplica(ctx context.Context, arg RecordReplicaParams) error {
	_, err := q.db.Exec(ctx, recordReplica,
		arg.ReplicaID,
		arg.Hostname,
		arg.Version,
		arg.KeyIds,
		arg.StartedAt,
		arg.RefreshedAt,
	)
	return err
}

